    public static function obtenerObjConfigConceptosContables($idconceptoscontables)
    {
        return Doctrine::getTable('ConfigConceptosContables')->find($idconceptoscontables);
    }

    public static function obtenerListadoConfigConceptosContables($idestructura, $criterio, $inicio = 0, $limite = 20)
    {
        $w = (!empty($criterio)) ? "AND (SELECT split_part(c.denominacion, '-', 1)) ilike '%" . $criterio . "%'" : '';
        $limit = " limit $limite offset $inicio";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        //Devolviendo el listado de tipos de nomina en forma de arreglo.
        $sql = "SELECT c.*, cce.obligacion
                FROM mod_nomina.conf_conceptoscontables c
                INNER JOIN mod_nomina.conf_conceptoscontablesentidad cce ON  cce.idconceptocontable = c.idconceptoscontables
                WHERE cce.idestructura = ? ".$w. $limit;
        $r = $conn->fetchAll($sql, array($idestructura));
        return $r;
    }

    public static function obtenerListadoTodosConfigConceptosContables($idtiponomina)
    {
        //Devolviendo el listado de tipos de n�mina en forma de arreglo.
        return Doctrine_Query::create()
            ->select('denominacion, idestructuramodelodomina')
            ->where('idtiponomina = ?', array($idtiponomina))
            ->from('ConfigConceptosContables')
            ->fetchArray();
    }

